          "labelShort": {
            "type": "string",
            "description": "窗帘勾选项的短标签。",
            "sampleValue": "帘"
          },
          "selected": {
            "type": "boolean",
            "description": "窗帘是否勾选进入离家模式。",
            "sampleValue": true
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋语义图标，来自场景库，适合用作智能家居入口或离家模式主视觉。"
    }
  ]
}

